from src.state.arch_state import ArchitectureOutput
from src.agents.database_agent import DatabaseDesignerAgent


class SQLCompiler:
    @staticmethod
    def compile(arch: ArchitectureOutput) -> str:
        lines = [
            "-- ========================================================",
            "-- Auto-Generated Production Relational Schema (PostgreSQL)",
            "-- Generated by Deterministic Multi-Agent Architecture Engine",
            "-- ========================================================\n",
            'CREATE EXTENSION IF NOT EXISTS "uuid-ossp";',
            'CREATE EXTENSION IF NOT EXISTS "pgcrypto";\n'
        ]

        identifier = DatabaseDesignerAgent._sql_identifier

        # 1. Table Definitions
        for table_name, columns in arch.tables_ddl.items():
            sql_table_name = DatabaseDesignerAgent._table_identifier(table_name)
            cols_joined = ",\n    ".join(columns)

            stmt = (
                f"CREATE TABLE IF NOT EXISTS {sql_table_name} (\n"
                f"    {cols_joined}\n"
                f");\n"
            )
            lines.append(stmt)

        # 2. Performance and Foreign Key Indexes
        if arch.indexes:
            lines.append("-- Performance & Foreign Key Lookup Indexes")

            for idx in arch.indexes:
                lines.append(idx)

            lines.append("")

        return "\n".join(lines)